// Phase U samples: tiny embedded images for the sprite / Layer Map
// starters. SPRITE_STAR is a white 5-point star on transparency
// (96x96 PNG, the sprite's luminance x alpha becomes the particle
// shape); MAP_BLOB is an opaque radial blob (white centre fading to
// black) used as the gradient-image source the Layer Map samples.
const SAMPLE_SPRITE_STAR = 'data:image/png;base64,';

// Phase AD sample: a 4x1 flipbook sheet (128x32) — four discs of
// growing radius, so an age-driven particle visibly swells frame
// by frame over its life.
const SAMPLE_SPRITE_SHEET_GROW = 'data:image/png;base64,';
const SAMPLE_MAP_BLOB = 'data:image/png;base64,';

// Phase X sample: a 64x64 ring luminance map for the raster-mask
// starter, computed (not embedded) so the numeric mask map the
// bake consumes is exact — 1 inside the annulus, 0 elsewhere.
const SAMPLE_MASK_RING = (() => {
  const width = 64;
  const height = 64;
  const map = new Array<number>(width * height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const nx = ((x + 0.5) / width) * 2 - 1;
      const ny = ((y + 0.5) / height) * 2 - 1;
      const r = Math.sqrt(nx * nx + ny * ny);
      map[y * width + x] = r >= 0.38 && r <= 0.82 ? 1 : 0;
    }
  }
  return { map, width, height };
})();

// Phase BF sample: a disc luminance map used as the Boolean
// operand, and the crescent composed from the ring minus this
// disc with lib/shapeBoolean.ts at module load — so the
// crescent starter's mask map is the exact output of the same
// code the UI's combine button runs.
const SAMPLE_MASK_DISC = (() => {
  const width = 64;
  const height = 64;
  const map = new Array<number>(width * height);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const nx = ((x + 0.5) / width) * 2 - 1;
      const ny = ((y + 0.5) / height) * 2 - 1;
      const dx = nx - 0.34;
      const dy = ny + 0.12;
      map[y * width + x] = dx * dx + dy * dy <= 0.52 * 0.52 ? 1 : 0;
    }
  }
  return { map, width, height };
})();

const SAMPLE_MASK_CRESCENT = (() => {
  const combined = combineLumaMaps(
    SAMPLE_MASK_RING.map, SAMPLE_MASK_RING.width, SAMPLE_MASK_RING.height,
    SAMPLE_MASK_DISC.map, SAMPLE_MASK_DISC.width, SAMPLE_MASK_DISC.height,
    'difference',
  );
  return {
    map: combined ? Array.from(combined) : SAMPLE_MASK_RING.map,
    width: SAMPLE_MASK_RING.width,
    height: SAMPLE_MASK_RING.height,
  };
})();

